///|
fn repository_slug(repository : String) -> String {
  let raw_name = repository
    .trim_end(chars="/")
    .split("/")
    .to_array()
    .last()
    .unwrap()
    .split(":")
    .to_array()
    .last()
    .unwrap()
    .to_owned()
  let name = raw_name
    .strip_suffix(".git")
    .unwrap_or(raw_name)
    .to_owned()
    .to_lower()
  let slug = StringBuilder()
  let mut separator = false
  let mut started = false
  for c in name {
    if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') {
      if separator && started {
        slug.write_string("-")
      }
      slug.write_char(c)
      separator = false
      started = true
    } else {
      separator = true
    }
  }
  let slug = slug.to_string()
  if slug == "" {
    "repo"
  } else {
    slug
  }
}

///|
fn workspace_name(slug : String) -> String raise {
  let alphabet = "REDACTED"
  for attempt = 0; attempt < 32; attempt = attempt + 1 {
    guard @env.rand(3) is Some(bytes) else {
      raise AdapterError("Workspace naming requires platform randomness")
    }
    if bytes[1].to_int() >= 252 || bytes[2].to_int() >= 252 {
      continue
    }
    let animal = workspace_animals[bytes[0].to_int() %
      workspace_animals.length()]
    let limit = 48 - animal.length() - 4
    let prefix = if slug.length() > limit {
      slug[0:limit].to_owned().trim_end(chars="-").to_owned()
    } else {
      slug
    }
    return prefix +
      "-" +
      animal +
      "-" +
      alphabet[bytes[1].to_int() % 36].to_string() +
      alphabet[bytes[2].to_int() % 36].to_string()
  }
  raise AdapterError("Unable to generate workspace name")
}

///|
async fn workspace_creation_lock() -> @fs.File {
  let directory = adapter_state_home()
  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
  let lock = @fs.open(
    directory + "/create.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  errdefer lock.close()
  @async.with_timeout(600000, async fn() {
    while !lock.try_lock(Exclusive) {
      @async.sleep(100)
    }
  })
  lock
}

///|
async fn select_workspace_name(
  state : Json,
  repository : String,
  generate~ : (String) -> String raise = workspace_name,
) -> Unit {
  let slug = repository_slug(repository)
  for attempt = 0; attempt < 64; attempt = attempt + 1 {
    let id = generate(slug)
    set_field(state, "workspaceId", Json::string(id))
    let occupied = workspace(state) is Some(_)
    save_diagnostic(
      "workspace-name",
      if occupied {
        "collision"
      } else {
        "selected"
      },
      attempt=attempt + 1,
      source=IdentitySelection(slug, id),
    )
    if !occupied {
      return
    }
  }
  raise AdapterError("Unable to reserve an unused workspace name")
}
///|
async fn server_connection(
  state : Json,
  install : Bool,
  deadline? : UInt64,
) -> Json {
  if install && field(state, "orcaVolume") is None {
    let script = server_install_script()
    ignore(remote(state, script, "orca-install"))
  }
  let output = recover_server(state, connection_result=true)
  ensure_ssh_worker(state, Some(reserve_server_port(state)), deadline?)
  output
}

///|
async fn recover_server(
  state : Json,
  connection_result~ : Bool = false,
) -> Json {
  let directory = required(state, "tunnelDirectory")
  let lock = @fs.open(
    directory + "/server.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  @async.with_timeout(30000, async fn() {
    while !lock.try_lock(Exclusive) {
      @async.sleep(100)
    }
  })
  guard @fs.exists(directory + "/enabled") && !@fs.exists(directory + "/paused") else {
    raise AdapterError("Connection recovery cancelled")
  }
  let output = if !connection_result && server_is_running(state) {
    save_diagnostic("recover-server", "reuse", tunnel_directory=directory)
    Json::null()
  } else {
    save_diagnostic("recover-server", "start", tunnel_directory=directory)
    if field(state, "orcaVolume") is Some(_) {
      prepare_orca_storage(state)
      ignore(remote(state, server_install_script(), "orca-install"))
    }
    let output = launch_server(state)
    configure_orca_project(state)
    output
  }
  @fs.write_file(directory + "/server-enabled", "", permission=0o600)
  output
}

///|
async fn launch_server(state : Json) -> Json {
  let root = required(state, "projectRoot")
  let port = reserve_server_port(state)
  let script = (if field(state, "orcaVolume") is Some(_) {
      "export ORCA_USER_DATA_PATH=/workspaces/.orca/.profile; "
    } else {
      ""
    }) +
    server_launch_script(root, port)
  let result = @json.parse(remote(state, script, "orca-serve"))
  let connection = match field(result, "connection") {
    Some(value) => value
    None => result
  }
  guard required(connection, "pairingCode") != "" else {
    raise AdapterError("Orca returned no pairing code")
  }
  let output : Json = {
    "type": "orca-server",
    "pairingCode": required(connection, "pairingCode"),
    "projectRoot": root,
  }
  output
}

///|
fn server_launch_script(root : String, port : Int32) -> String {
  // The Linux wrapper in 1.4.224 resolves the app root inside app.asar.unpacked.
  // Invoke the package-declared CLI entry so Orca prepares its bundled orcad.
  "ELECTRON_RUN_AS_NODE=1 exec \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" \"$HOME/.local/share/orca-env-devsy/orca/current/resources/app.asar/out/cli/index.js\" serve --recipe-json --project-root " +
  quote(root) +
  " --port 47121 --pairing-address " +
  quote("ws://127.0.0.1:\{port}") +
  // A detached server must not retain the SSH channel's stderr pipe.
  " 2>/dev/null"
}

///|
