///|
async fn restart_tunnel(state : Json, directory : String) -> Unit {
  let enabled = directory + "/enabled"
  let was_enabled = @fs.exists(enabled)
  errdefer (if was_enabled && @fs.exists(directory) {
    @fs.write_file(enabled, "", permission=0o600) catch {
      _ => ()
    }
      save_diagnostic("recover", "failed")
      raise AdapterError("Bulk recover failed")
    }
  }
}

///|
async fn recover_all_inner(restart~ : Bool = false) -> Unit {
  notify(if restart { "restart" } else { "recover" })
  let base = adapter_state_home() + "/tunnels"
  if !@fs.exists(base) {
    save_diagnostic("recover", "success")
    return
  }
  ignore(saved_proxy_executable())
  let mut failures = 0
  let permits = @async.Semaphore(4)
  @async.with_task_group(async fn(group) {
    for name in @fs.readdir(base, sort=true) {
      let directory = base + "/" + name
      permits.acquire()
      group.spawn_bg(async fn() {
        defer permits.release()
        try {
          if @fs.kind(directory, follow_symlink=false) !=
            @fs.FileKind::Directory ||
            !@fs.exists(directory + "/enabled") {
            return
          }
          let state = @json.parse(
            @fs.read_file(directory + "/state.json").text(),
          )
          validate_state(state)
          set_field(state, "tunnelDirectory", Json::string(directory))
          recover_connection(state, restart~)
        } catch {
          _ =>
            if @fs.exists(directory) {
              failures += 1
              save_diagnostic("recover", "failed", tunnel_directory=directory)
            } else {
              save_diagnostic("recover", "target-removed")
            }
        }
      })
    }
  })
  guard failures == 0 else {
    raise AdapterError(
      "Some connections could not be recovered; other targets were attempted",
    )
  }
  save_diagnostic("recover", "success")
}

///|
async fn connection_operation_lock(state : Json) -> @fs.File {
  let directory = required(state, "tunnelDirectory")
  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
  let lock = @fs.open(
    directory + "/operation.lock",
  } else {
    // Saved receipts from before the recovery worker own an SSH master only.
    ignore(
      @process.collect_output(
        "ssh",
        ssh_args(state) + ["-S", control_socket(state, directory), "-O", "exit"],
      ),
    )
  }
  // Only remove this worker's files; retain unexpected directory contents.
  for
    name in [
      "state.json", "state.tmp", "status.json", "status.tmp", "worker.lock", "startup.lock",
      "socket", "git-status", "git-established", "probe-request", "recovery.lock",
      "operation.lock", "server.lock", "server-enabled", "paused", "pause-ack",
    ] {
    if @fs.exists(directory + "/" + name) {
      @fs.remove(directory + "/" + name)
    }
  }
  @fs.rmdir(directory) catch {
    _ => ()
  }
  progress_message("ssh-tunnel-close: done (" + progress_timing(started) + ")")
}

///|
pub async fn tunnel_worker(directory : String) -> Unit {
  let lock = @fs.open(
    directory + "/worker.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  if !lock.try_lock(Exclusive) {
    return
  }
  let state = @json.parse(@fs.read_file(directory + "/state.json").text())
  validate_state(state)
  let forwarding = match field(state, "localPort") {
    Some(Json::Number(value, ..)) =>
      ["-L", "127.0.0.1:\{value.to_int()}:127.0.0.1:47121"]
    None if field(state, "connection") == Some(Json::string("ssh")) => []
    _ => raise AdapterError("Missing tunnel port")
  }
  let enabled = directory + "/enabled"
  let mut adopted = try {
    check_tunnel(state, directory)
    true
  } catch {
    _ => false
  }
  set_field(state, "tunnelDirectory", Json::string(directory))
  let mut attempt = 0
  let mut monitoring = false
  let mut monitor_attempt = 0
  defer @async.protect_from_cancel(async fn() {
    stop_tunnel_master(state, directory)
  })
  while @fs.exists(enabled) {
    if pause_request(directory) is Some(request) {
      stop_tunnel_master(state, directory)
      tunnel_status(directory, "paused")
      while @fs.exists(enabled) && pause_request(directory) == Some(request) {
        @fs.write_file(directory + "/pause-ack", request, permission=0o600)
        @async.sleep(100)
      }
      continue
    }
    if @fs.exists(directory + "/probe-request") {
      @fs.remove(directory + "/probe-request")
    }
    tunnel_status(directory, "connecting")
    git_relay_status(directory, "pending")
    let mut terminal = false
    @async.with_task_group(async fn(group) {
      group.spawn_bg(no_wait=true, async fn() {
        while @fs.exists(enabled) && !@fs.exists(directory + "/paused") {
          @async.sleep(100)
        }
    set_field(state, "buildCommit", Json::string(actual_commit))
    if mode == "provisioned-root" {
      create_recording.phase = "task-checkout"
      let head = environment("ORCA_REPO_REF_HEAD")
      let branch = environment("ORCA_REPO_BRANCH")
      guard valid_commit(head) && !branch.has_prefix("-") else {
        raise AdapterError("Invalid provisioned-root checkout identity")
      }
      let present = remote(
        state,
        "cd " +
        quote(root) +
        " && if git cat-file -e " +
        quote(head + "^{commit}") +
        " 2>/dev/null; then printf present; else printf missing; fi",
        "task-commit-presence",
      )
      match present {
        "present" => ()
        "missing" => wait_git_relay(required(state, "tunnelDirectory"))
        _ => raise AdapterError("Invalid task commit presence result")
      }
      ignore(
        remote(state, checkout_script(root, head, branch), "checkout-workspace"),
      )
    }
    false
  })
  if retry {
    discard_created_workspace(state)
    save_diagnostic("create-attempt", "retry")
    attempt_complete = true
    create_state(pinned_commit=environment("ORCA_REPO_REF_HEAD"))
  } else {
    attempt_complete = true
    save_diagnostic("create-attempt", "success")
    (state, deadline)
  }
}

///|
fn git_object_storage_script(root : String) -> String {
  // FUSE filesystems can transiently hide objects created via link/unlink. Git's rename
  // mode avoids that sequence; retain an explicit user configuration.
  "cd " +
  quote(root) +
  " && " +
  (
    #|filesystem=$(stat -f -c %T .) || exit
    #|case "$filesystem" in virtiofs|fuseblk) ;; *) exit 0 ;; esac
    #|for attempt in 1 2 3 4 5; do
    }
    AdapterError(message) => {
      progress_message(message + " (" + progress_timing(progress_started) + ")")
      save_diagnostic(mode, "failed")
      raise AdapterError(message)
    }
    _ => {
      progress_message(
        mode + ": failed (" + progress_timing(progress_started) + ")",
      )
      save_diagnostic(mode, "failed")
      raise AdapterError(
        mode +
        " failed: unexpected runtime error; diagnostic run " +
        recording_run_id,
      )
    }
  }
}

///|
fn validate_state(state : Json) -> Unit raise {
  ignore(saved_command(state))
  guard valid_workspace_id(required(state, "workspaceId")) &&
    valid_user(required(state, "user")) else {
    raise AdapterError("Invalid workspace identity")
  }
}

///|
async fn workspace(state : Json) -> Json? {
  let listing = @json.parse(
    devsy(
      state,
      ["--result-format", "json", "workspace", "list", "--skip-pro"],
      "workspace-list",
    ),
  )
  guard listing is Json::Array(items) else {
    raise AdapterError("Invalid workspace list")
  }
  let matches = items.filter(item => {
    field(item, "id") == field(state, "workspaceId")
  })
  match matches {
    [] => None
    [single] => Some(single)
    _ => raise AdapterError("Duplicate workspace ID")
  }
}

///|
fn valid_commit(value : String) -> Bool {
  (value.length() == 40 || value.length() == 64) &&
  value
  .to_array()
  .iter()
  .all(c => (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))
}

///|
pub async fn usage_error() -> Unit {
  @stdio.stderr.write(
    "Usage: orca-env-devsy <create|resume|suspend|destroy|recover [--receipt]|restart [--receipt]>\n",
  )
  raise AdapterError("Invalid command")
}

///|
let location_variables : Array[String] = [
  "HOME", "DEVSY_HOME", "XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_CACHE_HOME", "XDG_STATE_HOME",
  "XDG_RUNTIME_DIR",
]

///|
async fn discard_created_workspace(state : Json) -> Unit {
  @async.protect_from_cancel(async fn() {
    try {
      @async.with_timeout(45000, async fn() {
        guard workspace(state) is Some(current) &&
          field(current, "uid") == field(state, "workspaceUid") else {
          return
        }
        if field(state, "user") is Some(_) {
          @async.with_timeout(15000, async fn() { close_tunnel(state) }) catch {
            _ => {
              save_diagnostic(
                "create-cleanup-tunnel",
                "warning",
                error_type="tunnel_cleanup",
              )
              @stdio.stderr.write(
                "orca-env-devsy: warning: tunnel cleanup failed; continuing workspace deletion\n",
              )
            }
          }
        }
        ignore(
          devsy(
            state,
            [
              "workspace",
              "delete",
              required(state, "workspaceId"),
              "--ignore-not-found",
            ],
            "create-cleanup",
          ),
        )
      })
      save_diagnostic("create-cleanup", "success")
    } catch {
      _ => {
        @stdio.stderr.write(
          "orca-env-devsy: warning: create cleanup failed; inspect the workspace with Devsy\n",
        )
        save_diagnostic("create-cleanup", "warning")
      }
    }
  })
}

